{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "HTTPS traffic only is disabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The attribute `enable_https_traffic_only` is explicitly set to false, allowing unencrypted HTTP traffic to the storage account, which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_AZURE_59",
      "title": "Public network access not restricted",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not configure `public_network_access_enabled = false`, leaving it open to public internet access by default, which increases the attack surface for SCADA-related data."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Blob anonymous access not restricted",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not set `min_tls_version` or `blob_properties` with `delete_retention_policy` and `container_delete_retention_policy`, but more critically, it lacks explicit configuration to deny anonymous blob access (`allow_blob_public_access` defaults to true in older API versions or if not managed via policy). While modern Azure defaults are safer, explicit hardening is required for compliance."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n  public_network_access_enabled = false\n  min_tls_version          = \"TLS1_2\"\n  allow_blob_public_access = false\n}",
  "fix_summary": "Enabled HTTPS-only traffic, disabled public network access, enforced TLS 1.2 minimum, and explicitly denied blob public access to secure the storage account against eavesdropping and unauthorized access."
}
